insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('case-videos','case-videos',false,26214416,array['application/octet-stream']) on conflict(id) do nothing;
create table private.case_videos(id uuid primary key,case_hash text not null references private.private_cases(token_hash) on delete cascade,path text not null unique,payload jsonb not null,status text not null default 'pending' check(status in ('pending','complete')),created_at timestamptz not null default now());
alter table private.case_videos enable row level security;grant all on private.case_videos to service_role;create index case_videos_case on private.case_videos(case_hash);
create function public.begin_case_video(p_id uuid,p_hash text,p_path text,p_payload jsonb) returns boolean language plpgsql security definer set search_path='' as $$ begin
 perform 1 from private.private_cases where token_hash=p_hash and revoked_at is null and expires_at>now() for update;if not found then raise exception 'Active case required';end if;
 if (select count(*) from private.case_videos where case_hash=p_hash)>=3 or p_path<>p_hash||'/'||p_id::text or octet_length(p_payload::text)>6000 then raise exception 'Bounded private video limit';end if;
 insert into private.case_videos(id,case_hash,path,payload) values(p_id,p_hash,p_path,p_payload);return true;end $$;
create function public.case_videos(p_hash text) returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'path',v.path,'payload',v.payload,'status',v.status,'createdAt',v.created_at)),'[]'::jsonb) from private.case_videos v join private.private_cases c on c.token_hash=v.case_hash where c.token_hash=p_hash and c.revoked_at is null and c.expires_at>now(); $$;
create function public.complete_case_video(p_id uuid,p_hash text) returns boolean language plpgsql security definer set search_path='' as $$ begin update private.case_videos set status='complete' where id=p_id and case_hash=p_hash and exists(select 1 from private.private_cases where token_hash=p_hash and revoked_at is null and expires_at>now());return found;end $$;
revoke all on function public.begin_case_video(uuid,text,text,jsonb),public.case_videos(text),public.complete_case_video(uuid,text) from public,anon,authenticated;grant execute on function public.begin_case_video(uuid,text,text,jsonb),public.case_videos(text),public.complete_case_video(uuid,text) to service_role;
